Problem:
A food distributer can either move their product using trucks or boats. A truck can take 30 units of product and produces 80 units of pollution per trip whereas boats take 50 units of product and produces 60 units of pollution per trip. The food distributer needs to move 1000 units of product and must have a maximum of 40% of the trips using boats due to limitations of sea transportation regulations. Additionally, there must be at least 10 trips using a truck. How many of each form of transportation should be used to minimize the total amount of pollution produced?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "truck trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "boat trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "truck trips",
     "coef": 80.0
    },
    {
     "var": "boat trips",
     "coef": 60.0
    }
   ]
  },
  "constraints": [
   {
    "name": "product moved",
    "terms": [
     {
      "var": "truck trips",
      "coef": 30.0
     },
     {
      "var": "boat trips",
      "coef": 50.0
     }
    ],
    "sense": ">=",
    "rhs": 1000.0
   },
   {
    "name": "boat trip share at most 40%",
    "terms": [
     {
      "var": "boat trips",
      "coef": 0.6
     },
     {
      "var": "truck trips",
      "coef": -0.4
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   },
   {
    "name": "at least 10 truck trips",
    "terms": [
     {
      "var": "truck trips",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 10.0
   }
  ]
 },
 "facts": {
  "objective": 1960.0,
  "values": {
   "truck trips": 17.0,
   "boat trips": 10.0
  },
  "binding": [],
  "slack": {
   "product moved": 10.0,
   "boat trip share at most 40%": 0.8,
   "at least 10 truck trips": 7.0
  },
  "shadow_prices": null,
  "limits": {
   "product moved": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "boat trip share at most 40%": {
    "dropped_improves": true,
    "loosened_improves": true
   },
   "at least 10 truck trips": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
